import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.DGvnA5EY.js";const i="/workbuddy-guide/assets/01-system-hub.DwSSXCZ3.png",l="/workbuddy-guide/assets/02-road-ahead.8zBnrnwQ.png",h=JSON.parse('{"title":"课外阅读：一章看懂 AI 工作系统","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 前十章像是在学做菜：每章教一个零件——建任务、配工作区、装技能、请专家、 连账号、定闹钟、发遥控。这一章不教你新按钮，而是把十个章节拼成一张完整的 地图。读完它，你就知道自己手里这台机器的全貌了。","frontmatter":{"title":"课外阅读：一章看懂 AI 工作系统"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/课外阅读：一章看懂 AI 工作系统/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/课外阅读：一章看懂 AI 工作系统/index.md","lastUpdated":1791626462000}'),e={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/课外阅读：一章看懂 AI 工作系统/index.md"};function n(s,r,p,b,g,u){return t(),a("div",null,[...r[0]||(r[0]=[d('<h1 id="课外阅读-一章看懂-ai-工作系统" tabindex="-1">课外阅读：一章看懂 AI 工作系统 <a class="header-anchor" href="#课外阅读-一章看懂-ai-工作系统" aria-label="Permalink to &quot;课外阅读：一章看懂 AI 工作系统&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前十章像是在学做菜：每章教一个零件——建任务、配工作区、装技能、请专家、 连账号、定闹钟、发遥控。这一章不教你新按钮，而是把十个章节<strong>拼成一张完整的 地图</strong>。读完它，你就知道自己手里这台机器的全貌了。</p><h2 id="一、先做一套课后自测题" tabindex="-1">一、先做一套课后自测题 <a class="header-anchor" href="#一、先做一套课后自测题" aria-label="Permalink to &quot;一、先做一套课后自测题&quot;">​</a></h2><p>在往下读之前，先做个小测验。下面 7 道题全部来自前十章， 答不上来的，回到对应章节复习一遍——这比继续往后读更有价值。</p><ul><li>[ ] 用自己的话说出「聊天机器人」和 WorkBuddy（AI Agent）的区别。（第 1 章）</li><li>[ ] 工作区是什么？为什么处理不同的事要用不同的工作区？（第 3 章）</li><li>[ ] Skill 怎么加载？加载之后怎么在对话里用起来？（第 5 章）</li><li>[ ] 专家和专家团有什么区别？什么样的任务值得请&quot;一团&quot;专家？（第 6 章）</li><li>[ ] 连接器接入一个外部账号（比如 QQ 邮箱）大致几步？为什么要&quot;信任&quot;？（第 7 章）</li><li>[ ] 什么样的任务适合交给自动化？无人值守时最该注意什么？（第 10 章）</li><li>[ ] （加分题）不坐在电脑前，你有哪两种方式给 WorkBuddy 派活、收结果？（第 8 章）</li></ul><h2 id="二、一张图看懂-ai-工作系统" tabindex="-1">二、一张图看懂 AI 工作系统 <a class="header-anchor" href="#二、一张图看懂-ai-工作系统" aria-label="Permalink to &quot;二、一张图看懂 AI 工作系统&quot;">​</a></h2><p>把 WorkBuddy 想成<strong>一家只有一名万能员工的公司</strong>：你是老板， 它同时兼任文员、分析师、程序员和跑腿。前十章教你的零件， 在这家公司里各有一个明确的岗位：</p><div style="display:flex;flex-wrap:wrap;gap:10px;margin:12px 0;"><div style="flex:1 1 140px;min-width:140px;background:var(--wb-bg-card,#FBF8F1);border:1px solid var(--wb-border,rgba(42,32,24,0.12));border-radius:12px;padding:12px 14px;color:var(--wb-ink,#2A2018);"><strong>🧩 技能 Skill</strong><br><span style="color:var(--wb-body,#6F6151);">培训手册与工具箱，让它干活更专业（第 5 章）</span></div><div style="flex:1 1 140px;min-width:140px;background:var(--wb-bg-card,#FBF8F1);border:1px solid var(--wb-border,rgba(42,32,24,0.12));border-radius:12px;padding:12px 14px;color:var(--wb-ink,#2A2018);"><strong>👔 专家 Expert</strong><br><span style="color:var(--wb-body,#6F6151);">请来的资深顾问或顾问团，按角色出谋划策（第 6 章）</span></div><div style="flex:1 1 140px;min-width:140px;background:var(--wb-bg-card,#FBF8F1);border:1px solid var(--wb-border,rgba(42,32,24,0.12));border-radius:12px;padding:12px 14px;color:var(--wb-ink,#2A2018);"><strong>🔌 连接器 Connector</strong><br><span style="color:var(--wb-body,#6F6151);">门禁卡加电话线，接上邮箱、文档和外部系统（第 7 章）</span></div><div style="flex:1 1 140px;min-width:140px;background:var(--wb-bg-card,#FBF8F1);border:1px solid var(--wb-border,rgba(42,32,24,0.12));border-radius:12px;padding:12px 14px;color:var(--wb-ink,#2A2018);"><strong>⏰ 自动化 Automation</strong><br><span style="color:var(--wb-body,#6F6151);">定时闹钟，到点自动开工，无人值守出活（第 10 章）</span></div><div style="flex:1 1 140px;min-width:140px;background:var(--wb-bg-card,#FBF8F1);border:1px solid var(--wb-border,rgba(42,32,24,0.12));border-radius:12px;padding:12px 14px;color:var(--wb-ink,#2A2018);"><strong>📱 小程序与 IM 助理</strong><br><span style="color:var(--wb-body,#6F6151);">遥控器加展示屏，不在电脑前也能派活收活（第 8 章）</span></div></div><p><img src="'+i+'" alt="一只小黑站在圆形系统的边缘，圆心有橙色节点，几条细线向四周辐射出小圆圈" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;以任务为中心、模块向外辐射&quot;的系统结构，与实际软件界面无关。</em></p><p>这张图的读法：<strong>圆心是&quot;任务&quot;</strong>。所有模块都是围绕任务服务的—— 技能让任务做得更专业，连接器让任务够得着外部世界，自动化让任务自己 触发，小程序和 IM 助理让你在圆外也能往圆心投任务、从圆心收结果。 第 9 章接入外部 API 之后，这张网还能继续往外扩。</p><h2 id="三、零件怎么配合-一条完整的工作流" tabindex="-1">三、零件怎么配合：一条完整的工作流 <a class="header-anchor" href="#三、零件怎么配合-一条完整的工作流" aria-label="Permalink to &quot;三、零件怎么配合：一条完整的工作流&quot;">​</a></h2><p>光认识零件还不够，看它们<strong>连起来</strong>是什么样。设想一个真实需求： &quot;每周一早上 9 点，自动整理一份行业周报，推送到我微信上。&quot; 拆开看，它正好把五个模块全用上了：</p><ol><li><strong>自动化模块</strong>到点触发——闹钟响了（第 10 章）</li><li>系统生成一个<strong>任务</strong>——员工开工（第 3 章）</li><li>任务调用<strong>联网搜索</strong>能力查最新资料——翻工具箱（第 1、4 章）</li><li>通过<strong>连接器</strong>抓取你关注的资讯源——打外部电话（第 7、9 章）</li><li>按<strong>专家</strong>的分析框架整理成文——顾问给模板（第 6 章）</li><li>结果<strong>推送到小程序</strong>——成品递到你手上（第 8 章）</li></ol><p>你会发现：每个零件单看都很简单，但<strong>连起来就是一台不用盯着的机器</strong>。 这就是&quot;AI 工作系统&quot;和&quot;会用一个 AI&quot;的区别。</p><h2 id="四、你现在手里有什么" tabindex="-1">四、你现在手里有什么 <a class="header-anchor" href="#四、你现在手里有什么" aria-label="Permalink to &quot;四、你现在手里有什么&quot;">​</a></h2><p>盘点一下，读完第一篇，你已经会：</p><ul><li>装好并更新 WorkBuddy，登录自己的账号（第 2 章）</li><li>建任务、配工作区，把不同的事分门别类（第 3 章）</li><li>用三要素（提示词、上下文、期望产物）描述清楚一个任务（第 4 章）</li><li>加载技能、请专家，给 AI 换装和配智囊（第 5、6 章）</li><li>接上邮箱、文档等外部账号，甚至自己写配置接 API（第 7、9 章）</li><li>定时自动化，手机远程遥控（第 8、10 章）</li></ul><p>到此为止，你已经<strong>从&quot;会用一个 AI&quot;升级到&quot;拥有一套 AI 工作系统&quot;</strong>。 剩下的不是学更多按钮，而是把它用进你自己的真实场景。</p><h2 id="五、接下来去哪-课外阅读地图" tabindex="-1">五、接下来去哪：课外阅读地图 <a class="header-anchor" href="#五、接下来去哪-课外阅读地图" aria-label="Permalink to &quot;五、接下来去哪：课外阅读地图&quot;">​</a></h2><p><img src="'+l+'" alt="一只小黑手持地图，三条虚线路径通向远处三面小旗" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;三条进阶路线&quot;，与实际软件界面无关。</em></p><p>本指南后面三篇，按需取用，不必顺序通读：</p><table tabindex="0"><thead><tr><th>去处</th><th>里面有什么</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>第二篇 案例篇</strong>（第 11–21 章）</td><td>办公三件套、整理文件、远程控制、资讯整合、投资分析、AI 视频等 11 个真实案例</td><td>想马上照着做一个的</td></tr><tr><td><strong>第三篇 进阶篇</strong>（第 22–25 章）</td><td>打造自己的 Skill、多 Agent 系统设计、自动化可靠性</td><td>想把工作系统化的</td></tr><tr><td><strong>第四篇 岗位与行业落地</strong>（第 26–28 章）</td><td>不同岗位、不同行业的路线图</td><td>想看别人怎么用的</td></tr><tr><td><strong>附录</strong></td><td>常用指令模板、场景速查表</td><td>当字典随手翻</td></tr></tbody></table><p><strong>建议读法</strong>：先翻第二篇目录，挑一个最贴近你工作的案例照着做； 做出成就感后，再回第三篇补方法论。案例比概念更容易上瘾。</p><p>想看最新、最全的功能说明，随时去官方文档：<code>www.workbuddy.cn/docs</code> （本指南基于官方指南改写，若两处说法不一致，以官方为准）。</p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>AI Agent（智能体）</strong>：能自己拆步骤、调工具、动手干活的 AI，不只是陪你聊天。</p><p><strong>工作流（Workflow）</strong>：把一件事拆成固定的几步，让 AI 按顺序自动走完。</p><p><strong>触发器（Trigger）</strong>：让任务自动开工的开关，最常见的是&quot;到点就跑&quot;的定时触发。</p><p><strong>编排（Orchestration）</strong>：把技能、专家、连接器这些零件组织起来协同干活的机制。</p><p><strong>无人值守（Unattended）</strong>：没有你在场监督、AI 自动运行的状态，需要提前管好权限。</p><p><strong>闭环（Loop）</strong>：从派活、执行到收结果形成完整回路，不用人工中转。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 完成第一节的 7 道自测题，答不上的回对应章节复习</li><li>[ ] 在纸上画出 WorkBuddy 系统全景：中心是任务，五个模块向外辐射</li><li>[ ] 写下你最想自动化的 1 件重复性工作（第二篇很可能拿它当案例）</li><li>[ ] 翻开第二篇目录，圈出你最想先读的 3 个案例</li></ul><hr><p><em>下一篇：第二篇 案例篇——第 11 章办公三件套，把 Word、Excel、PPT 交给 AI。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',35)])])}const x=o(e,[["render",n]]);export{h as __pageData,x as default};
